export function createSession(){return {answers:Object.fromEntries(SCENES.map(s=>[s.id,null])),notes:Object.fromEntries(SCENES.map(s=>[s.id,'']))};}
export function setAnswer(state,id,answer){if(!SCENES.some(s=>s.id===id)||!CHOICES.some(c=>c.id===answer))throw new Error('Invalid decision');state.answers[id]=answer;}
export function setNote(state,id,note){if(!SCENES.some(s=>s.id===id)||typeof note!=='string')throw new Error('Invalid note');state.notes[id]=note.slice(0,500);}
export function calculateMetrics(state){const counts=Object.fromEntries(CHOICES.map(c=>[c.id,0]));for(const s of SCENES)if(state.answers[s.id])counts[state.answers[s.id]]++;const answered=Object.values(counts).reduce((a,b)=>a+b,0);const baseline=state.answers.offer;const changed=baseline?SCENES.slice(1).filter(s=>state.answers[s.id]&&state.answers[s.id]!==baseline).map(s=>s.id):[];return {counts,answered,complete:answered===6,baseline,changed,differences:changed.length,undecided:counts.undecided};}
export function buildRecord(state){const m=calculateMetrics(state);if(!m.complete)throw new Error('Complete all six decisions before exporting');return ['DNA / THE CHOICE','What changed your mind?','A personal record from a fictional speculative design exhibit.','Each situation changes one condition of the starting offer.','',`Differences from the initial answer: ${m.differences} of 5`,`Undecided answers: ${m.undecided} of 6`,`Choice counts: ${CHOICES.map(c=>`${c.short} ${m.counts[c.id]}`).join(' · ')}`,'',...SCENES.flatMap((s,i)=>[`${i+1}. ${s.short}`,narrativeFor(s.id)?.record||s.story,`Assumption: ${s.condition}`,`Answer: ${CHOICES.find(c=>c.id===state.answers[s.id]).label}`,`Comparison: ${i===0?'Initial answer':state.answers[s.id]===m.baseline?'Same as initial answer':'Different from initial answer'}`,`Reflection: ${s.question}`,`Private note: ${state.notes[s.id]||'(none)'}`,'']),'SOURCES',...SOURCES.flatMap(s=>[s.title,s.text,s.url,'']),'Original DNA project: Parth Pawar, NYU ITP, 2024.','https://designwhich.works/dna-speculative/','Responses are kept in memory only. This downloaded copy includes your notes.'].join('\n');}
